void
gen_oa_register_queries_cnl(struct gen_perf_config *perf)
{
   cnl_register_render_basic_counter_query(perf);
   cnl_register_compute_basic_counter_query(perf);
   cnl_register_render_pipe_profile_counter_query(perf);
   cnl_register_memory_reads_counter_query(perf);
   cnl_register_memory_writes_counter_query(perf);
   cnl_register_compute_extended_counter_query(perf);
   cnl_register_compute_l3_cache_counter_query(perf);
   cnl_register_hdc_and_sf_counter_query(perf);
   cnl_register_l3_1_counter_query(perf);
   cnl_register_l3_2_counter_query(perf);
   cnl_register_rasterizer_and_pixel_backend_counter_query(perf);
   cnl_register_sampler_counter_query(perf);
   cnl_register_tdl_1_counter_query(perf);
   cnl_register_tdl_2_counter_query(perf);
   cnl_register_test_oa_counter_query(perf);
}

